import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"山泽损","description":"周易折中 - 山泽损","frontmatter":{"title":"山泽损","description":"周易折中 - 山泽损"},"headers":[],"relativePath":"zh/classics/zhezhong/047.md","filePath":"zh/classics/zhezhong/047.md"}'),h={name:"zh/classics/zhezhong/047.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="山泽损" tabindex="-1">山泽损 <a class="header-anchor" href="#山泽损" aria-label="Permalink to “山泽损”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>〈损序卦〉解曰：“缓也。缓必有所失，故受之以损。纵缓则必有所失，失则损也。损所以继解也。为卦艮上兑下，山体高，泽体深，下深则上益高，为损。下益上之义也。又泽在山下，其气上通，润及草木百物，是损下而益上也。又下为兑说，三爻皆上应，是说以奉上，亦损下益上之义也。又下兑之成兑，由六三之变也，上艮之成艮，自上九之变也。三本刚而成柔，上本柔而成刚，亦损下益上之义。损上而益于下，则为益；取下而益于上，则为损。在人上者，施其泽以及下，则益也；取其下以自厚，则损也。譬诸垒土，损于上以培厚其基本，则上下安固矣，岂非益乎？取于下以増上之高，则危坠至矣，岂非损乎？故损者，损下益上之义；益则及是。”</p><p>损：有孚，元吉，无咎，可贞，利有攸往 【1】 ，曷之用，二簋可用享 【2】</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>【1】损，减省也。为卦损下卦上画之阳，益上卦上画之阴，损兑泽之深，益艮山之高，损下益上，损内益外，剥民奉君之象，所以为损也。损所当损而有孚信，则其占当有此下四者之应矣。</p><p>【2】言当损时则至薄无害。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>【1】损，减损也。凡损抑其过以就义理，皆损之道也。损之道必有孚诚，谓至诚顺于理也。损而顺理，则大善而吉，所损无过差，可贞固常行，而利有所往也。人之所损或过或不及或不常，皆不合正理，非有孚也。非有孚则无吉而有咎，非可贞之道，不可行也。</p><p>【2】损者，损过而就中，损浮末而就本实也。圣人以宁俭为礼之本，故为损发明其义，以享祀言之。享祀之礼，其文最繁，然以诚敬为本。多仪备物所以将饰其诚敬之心，饰过其诚则为伪矣。损饰所以存诚也，故云“曷之用二簋，可用享”。二簋之约，可用享祭，言在乎诚而已。诚为本也。天下之害，无不由末之胜也。峻宇雕墙本于宫室，酒池肉林本于饮食，淫酷残忍本于刑罚，穷兵黩武本于征讨。凡人欲之过者，皆本于奉养。其流之远，则为害矣。先王制其本者，天理也；后人流于末者，人欲也。损之义，损人欲以复天理而已。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>吕氏大临曰 ：损之道不可以为正当损之时，故曰可贞。时损则损，时益则益。苟当其时，无往而不可，故损益皆利有攸往。</p></li><li><p>蔡氏清曰 ：剥民奉君之义，只可用之卦名。其卦辞“有孚，元吉，无咎，可贞，利有攸往”，只承“损”字泛说，言损所当损，人人皆可用，不专指上之损下也。益卦“利有攸往，利涉大川”亦然，岂专为益下之事乎？</p></li><li><p>孔氏颖达曰 ：“曷之用二簋，可用享”者，明行损之礼贵夫诚信，不在于丰。二簋至约，可用享祭。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>彖辞自“有孚”以下泛说损所当损之义，蔡氏之说极为得之。盖损益者时也，时在当损，不得不损，惟以诚意为主而行之，又得乎大善之吉，则不但无咎，而且可以为常道而利有所往矣。举一端以明之，则如二簋薄祭，固因乎时而节损者也。然能积诚尽礼，则可以致孝乎鬼神，而推之凡事之当损者，视此矣。卦义以孚而行损，程传则因损以致孚，略有不同也。</p><p>象曰：山下有泽，损；君子以惩忿窒欲</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>君子修身所当损者，莫切于此。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>山下有泽，气通上润，与深下以增高，皆损下之象。君子观损之象，以损于己。在修身之道所当损者，唯忿与欲。故以惩戒其忿怒，窒塞其意欲也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>虞氏翻曰：兑说，故惩忿；艮止，故窒欲。</p></li><li><p>孔氏颖达曰：惩者，息其既往；窒者，闭其将来。惩窒互文而相足也。</p></li><li><p>杨氏时曰：损德之修也，所当损者惟忿欲而已。故九思始于视听貌言，终于忿思难见，得思义者以此。</p></li><li><p>朱子语类 问：何以窒欲？伊川云：思此莫是欲心一萌，当思礼义以胜之。否曰：然。</p></li><li><p>王氏申子曰：和说则无忿，知止则无欲。故曰脩德之要也。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>凡大象配两体之德者，皆先内后外，故当以虞氏之说为是。益象亦然。</p><p>彖曰：损，损下益上，其道上行</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦体释卦名义。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>损之所以为损者，以损于下而益于上也。取下以益上，故云其道上行。夫损上而益下则为益，损下而益上则为损。损基本以为高者，岂可谓之益乎？</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>蔡氏清曰 ：损下益上，利归于上也，故曰其道上行。下损则上不能独益矣，卦所以为损也。</p></li><li><p>林氏希元曰 ：损下益上，下损则上亦损，故曰其道上行。道者，损之道也。程传小注、蒙引俱作利归于上说，愚谓卦以损下取名，所重不在于利，又难以道为利。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>蔡氏、林氏两说沿袭用之，今思之于卦义皆未全。盖说者但主取民财一事耳，岂知如人臣之致身事主，百姓之服役奉公，皆损下益上之事也。必如此，然后上下交而志同，岂非其道上行乎？上行与“地道卑而上行”之义同，下能益上则道上行矣，上能益下则道大光矣。如此，则“道”字方有意味，而于两卦诸爻之义亦合。</p><p>损而有孚，元吉，元咎，可贞，利有攸往，曷之用？二簋可用享。二簋应有时，损刚益柔，有时损益盈虚，与时偕行</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>此释卦辞，时谓当损之时。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>谓损而以至诚，则有此兀吉以下四者，损道之尽善也。夫子特释“曷之用？二簋可用享”卦辞，简直谓当损去浮饰，曰何所用哉？二簋可以享也。厚本损末之谓也。夫子恐后人不逹，遂以为文饰当尽去，故详言之。有本必有末，有实必有文。天下万事无不然者，无本不立，无文不行。父子主恩，必有严顺之体；君臣主敬，必有承接之仪。礼让存乎内，待威仪而后行；尊卑有其序，非物采则无别。文之与实，相须而不可缺也。及夫文之胜，末之流逺，本丧实，乃当损之时也。故云“曷所用哉？二簋足以荐其诚矣”，谓当务实而损饰也。夫子恐人之泥言也，故复明之曰“二簋之质，用之当有时”，非其所用而用之不可也。谓文饰未过而损之，与损之至于过甚，则非也。损刚益柔有时，刚为过，柔为不足。损益皆损刚益柔也，必顺时而行。不当时而损益之，则非也。或损或益，或盈或虚，唯随时而已。过者损之，不足者益之，亏者盈之，实者虚之，与时偕行也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>徐氏几曰 ：卦辞曰“损有孚”，彖传曰“损而有孚”，加以“而”字，义晓然矣。</p></li><li><p>张氏清子曰 ：当其可之谓时，当损而损时也，不当损而损则非时。</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>程传之义施于贲卦则可，此卦所谓损者，乃谓时当节损，如家则称贫富之有无，国则视凶丰为丰俭之类耳。故曰“损而有孚”，言时虽不得已而损，而以有孚行之，如祭祀虽不能备品，而以至诚将之也。二簋喻节损之义，然下云“损刚益柔”者，非以损刚喻二簋也。刚为本，喻孚诚；柔为末，喻仪物。以孚诚之有馀，补仪物之不足，则虽二簋而不嫌于简矣，此损刚益柔之义。</p><p>初九：已事遄往，无咎，酌损之</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>初九当损下益上之时，上应六四之阴，辍所为之事而速往以益之，无咎之道也。故其象占如此，然居下而益上，亦当斟酌其浅深也。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>损之义，损刚益柔，损下益上也。初以阳刚应于四，四以阴柔居上位，赖初之益者也。下之益上，当损己而不自以为功，所益于上者事既已，则速去之，不居其功，乃无咎也。若享其成功之美，非损己益上也，于为下之道为有咎矣。四之阴柔赖初者也，故听于初。初当酌度其宜而损己以益之，过与不及皆不可也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li>孔氏颖逹曰 ：损之为道，损下益上，如人臣欲自损己奉上。然各有职掌，若废事而往，咎莫大焉。竟事速往，乃得无咎。酌损之者，以刚奉柔，初未见亲也，故须酌而减损之。</li></ul><p>孔氏颖逹曰 ：损之为道，损下益上，如人臣欲自损己奉上。然各有职掌，若废事而往，咎莫大焉。竟事速往，乃得无咎。酌损之者，以刚奉柔，初未见亲也，故须酌而减损之。</p><ul><li>朱子语类云 ：酌损之在损之初，下犹可以斟酌也。</li></ul><p>朱子语类云 ：酌损之在损之初，下犹可以斟酌也。</p><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>孔氏说“已事”之义，谓如学优而后从政之类，于理亦精。</p><p>象曰：已事遄往，尚合志也</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>尚，上通。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>尚，上也。时之所崇用为尚。初之所尚者，与上合志也。四赖于初，初益于四，与上合志也。</p><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>易例初九与六四虽正应，却无往从之义。在下位不援上也。惟损初爻言遄往，而传谓上合志，盖当损下益上之时故也。</p><p>九二：利贞，征凶，弗损益之</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>九二刚中，志在自守，不肯妄进，故占者利贞而征则凶也。弗损益之言，不变其所守，乃所以益上也。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>二以刚中当损刚之时，居柔而说体，上应六五阴柔之君。以柔说应上，则失其刚中之德，故戒所利在贞正也。征，行也。离乎中则失其贞正而凶矣。守其中乃贞也，弗损益之，不自损其刚贞，则能益其上，乃益之也。若失其刚贞而用柔说，适足以损之而已，非损己而益上也。世之愚者，虽无邪心而唯知竭力顺上为忠者，盖不知弗损益之之义也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li>林氏希元曰 ：九二在爻则为刚中，在人事则为志在自守，不肯妄进。志在自守，不肯妄进，九二之贞也。故占者利于守贞，若征行，则是变其所守而得凶矣。夫自守而不妄进，宜若无益于上矣，然由是而启时君尊德乐道之心，止士大夫奔竞之习，其益于上也不少。是弗损乃所以益之也。桐江一丝系汉九鼎，清风高节披拂士习，可当此爻之义。</li></ul><p>象曰：九二利贞，中以为志也</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>九居二，非正也；处说非刚也。而得中为善，若守其中，德何有不善？岂有中而不正者？岂有中而有过者？二所谓利贞，谓以中为志也。志存乎中，则自正矣。大率中重于正，中则正矣，正不必中也。能守中则有益于上矣。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰：言九二所以能居而守贞，不损益之良由，居中以中为志，故损益得其节适也。</p></li><li><p>王氏宗传曰：顺从为事，则在己者所损多矣。以道自守，乃所以益之，故曰九二利贞，中以为志也。中以为志，则在己者无失，而益上之实亦无出诸此。</p></li></ul><p>六三：三人行则损一人，一人行则得其友</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>下卦本干而损上爻以益坤，三人行而损一人也；一阳上而一阴下，一人行而得其友也。两相与则专，三则杂而乱，卦有此象，故戒占者当致一也。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>损者，损有馀也；益者，益不足也。三人谓下三阳上三阴。三阳同行，则损九三以益上三阴；同行，则损上六以为三。三人行则损一人也。上以柔易刚而谓之损，但言其减一耳。上与三虽本相应，由二爻升降而一卦皆成两相与也。初二二阳，四五二阴，同德相比，三与上应皆两相与，则其志专，皆为得其友也。三虽与四相比，然异体而应上，非同行者也。三人则损一人，一人则得其友。盖天下无不二者，一与二相对待，生生之本也。三则馀而当损矣。此损益之大义也。夫子又于系辞尽其义曰：“天地𬘡缊，万物化醇；男女构精，万物化生。《易》曰：‘三人行则损一人，一人行则得其友’，言致一也。”𬘡缊交密之状，天地之气相交而密，则生万物之化醇。醇谓𬪩厚，𬪩厚犹精一也。男女精气交构，则化生万物。惟精醇专一，所以能生也。一阴一阳岂可二也？故三则当损，吉专致乎一也。天地之间，当损益之明且大者，莫过此也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>林氏希元曰 ：此爻之辞兼举六爻，以三正是当损之爻，乃卦之所以为损者，故于此言之。</li></ul><p>林氏希元曰 ：此爻之辞兼举六爻，以三正是当损之爻，乃卦之所以为损者，故于此言之。</p><ul><li>杨氏启新曰 ：人之相与，惟其心之同而已。苟精神不孚，意气不贯，则群党比周，固三也；即一人之异，亦三也，是皆不可以不损也。苟精神相孚，意气相贯，则二人同心，固两也；即千百其朋，亦两也，是皆不可以不得者也。</li></ul><p>杨氏启新曰 ：人之相与，惟其心之同而已。苟精神不孚，意气不贯，则群党比周，固三也；即一人之异，亦三也，是皆不可以不损也。苟精神相孚，意气相贯，则二人同心，固两也；即千百其朋，亦两也，是皆不可以不得者也。</p><p>象曰：一人行三则疑也</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>一人行而得一人，乃得友也。若三人行，则疑所与矣。理当损去其一人，损其馀也。案自二以上，皆可以三概之，不必正三人也。季文子三思，南容三复之类。</p><p>六四：捐其疾，使遄有喜，无咎</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>以初九之阳刚益已而损其阴柔之疾，唯速则善，戒占者如是则无咎也。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>四以阴柔居上，与初之刚阳相应，在损时而应刚，能自损以从刚阳也，损不善以从善也。初之益四，损其柔而益之以刚，其不善损也。故曰“损其疾”，疾谓疾病，不善也。损于不善，唯使之遄速，则有喜而无咎。人之损过，唯患不速，速则不致于深过，为可喜也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏弼曰 ：履得其位，以柔纳刚，能损其疾也。疾何可久？故速乃有喜，有喜乃无咎也。</li></ul><p>王氏弼曰 ：履得其位，以柔纳刚，能损其疾也。疾何可久？故速乃有喜，有喜乃无咎也。</p><ul><li>苏氏轼曰 ：遄者，初九也。损其疾，则初之从我也易，故遄有喜。</li></ul><p>苏氏轼曰 ：遄者，初九也。损其疾，则初之从我也易，故遄有喜。</p><ul><li>杨氏万里曰 ：六四以柔居柔，得初九之阳以为应，损其疾者也。初言“遄往”，四言“使遄”，盖初之遄实四有以使之也。</li></ul><p>杨氏万里曰 ：六四以柔居柔，得初九之阳以为应，损其疾者也。初言“遄往”，四言“使遄”，盖初之遄实四有以使之也。</p><ul><li>胡氏炳文曰 ：六四与初九为应，初方巳其事而速于益四，四损其阴柔之疾，惟速则有喜，不然彼方汲汲，此乃悠悠，非受益之道。又曰：下损已以益上，当使下亦速，所喜乃无咎。</li></ul><p>胡氏炳文曰 ：六四与初九为应，初方巳其事而速于益四，四损其阴柔之疾，惟速则有喜，不然彼方汲汲，此乃悠悠，非受益之道。又曰：下损已以益上，当使下亦速，所喜乃无咎。</p><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>苏氏、杨氏说于“使”字语气亦近是。</p><p>象曰：损其疾亦可喜也</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>损其所疾，固可喜也。“亦”发语辞。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>项氏安世曰：能不吝其疾，自损以受之，使合志者得效其忠，岂非可喜之事哉。</li></ul><h3 id="案-7" tabindex="-1">案 <a class="header-anchor" href="#案-7" aria-label="Permalink to “案”">​</a></h3><p>易多言有喜，而此传云“亦可喜也”，则此喜不主己身，乃主于使遄来而益我者有喜。故变文曰“可喜者”，他人之辞也。</p><p>六五：或益之十朋之龟，弗克违，元吉</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>柔顺虚中以居尊位，当损之时，受天下之益者也。两龟为朋，十朋之龟，大宝也。或以此益之，而不能辞，其吉可知。占者有是德，则获其应也。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>六五于损时，以中顺居尊位，虚其中以应乎二之刚阳，是人君能虚中自损以顺从在下之贤也。能如是，天下孰不损己自尽以益之？故或有益之之事，则十朋助之矣。十朋，众辞。龟者，决是非吉凶之物，众人之公论必合正理，虽龟䇲不能违也。如此，可谓大善之吉矣。古人曰：“谋从众则合天心。”</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>张子曰 ：龟弗能违，言受益之可必，信然不疑也。</li></ul><p>张子曰 ：龟弗能违，言受益之可必，信然不疑也。</p><ul><li>杨氏时曰 ：柔得尊位，虚己而下人，则谦受益时乃天道。天且不违，况于人乎？况于鬼神乎？宜其益之者至矣。故曰“或益之十朋之龟，弗克违，元吉”。</li></ul><p>杨氏时曰 ：柔得尊位，虚己而下人，则谦受益时乃天道。天且不违，况于人乎？况于鬼神乎？宜其益之者至矣。故曰“或益之十朋之龟，弗克违，元吉”。</p><ul><li>郭氏雍曰 ：益之至，岂独人事而已，虽元龟之灵弗能违，此其所以元吉也。《洪范》曰：“汝则从龟从筮，从卿士，从庶民。”从是之谓大同。六五之元吉，犹《洪范》之大同也。</li></ul><p>郭氏雍曰 ：益之至，岂独人事而已，虽元龟之灵弗能违，此其所以元吉也。《洪范》曰：“汝则从龟从筮，从卿士，从庶民。”从是之谓大同。六五之元吉，犹《洪范》之大同也。</p><ul><li>杨氏时曰 ：“或者”不一之辞，益之者不一也，人心归之也。十朋之龟皆从而弗违，天与鬼神祐之也。鬼神祐之，故龟筮协从。</li></ul><p>杨氏时曰 ：“或者”不一之辞，益之者不一也，人心归之也。十朋之龟皆从而弗违，天与鬼神祐之也。鬼神祐之，故龟筮协从。</p><p>象曰：六五元吉，自上祐也</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>所以得元吉者，以其能尽众人之见，合天地之理，故自上天降之福祐也。</p><h3 id="案-8" tabindex="-1">案 <a class="header-anchor" href="#案-8" aria-label="Permalink to “案”">​</a></h3><p>自上祐以为正释，龟筮弗违亦可。然观益二言“朋龟不违”，下又云“享于帝吉”，则帝者又百神之主也。故此上祐，亦是言天心克享，人神不能违也。</p><p>上九：弗损益之，无咎，贞吉，利有攸往，得臣无家</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>上九当损下益上之时，居卦之上，受益之极而欲自损以益人也。然居上而益下，有所谓“惠而不费”者，不待损己然后可以益人也。能如是，则无咎。然亦必以正则吉，而利有所往。惠而不费，其惠广矣，故又曰“得臣无家”。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>凡损之义有三：损己从人也，自损以益于人也，行损道以损于人也。损己从人，徙于义也；自损益人，及于物也；行损道以损于人，行其义也。各因其时取大者言之。四五二爻取“损己从人”，下体三爻取“自损以益人”，损时之用；行损道以损天下之当损者也。上九则取“不行其损”为义。九居损之终，损极而当变者也。以刚阳居上，若用刚以损削于下，非为上之道，其咎大矣。若不行其损变，而以刚阳之道益于下，则无咎而得其正且吉也。如是，则宜有所往，往则有益矣。在上能不损其下而益之，天下孰不服从？从服之众无有内外也，故曰“得臣无家”。得臣，谓得人心归服；无家，谓无有远近内外之限也。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li>王氏肃曰 ：处损之极，损极则益，故曰“不损益之”。得臣，则万方一轨，故无家也。</li></ul><p>王氏肃曰 ：处损之极，损极则益，故曰“不损益之”。得臣，则万方一轨，故无家也。</p><ul><li>句氏微曰 ：上九刚德为物所归，虽曰得臣，非已所有，盖以四海为家。</li></ul><p>句氏微曰 ：上九刚德为物所归，虽曰得臣，非已所有，盖以四海为家。</p><ul><li>朱子语类云 ：得臣有家，其所得也小矣；无家则可见其大。</li></ul><p>朱子语类云 ：得臣有家，其所得也小矣；无家则可见其大。</p><h3 id="案-9" tabindex="-1">案 <a class="header-anchor" href="#案-9" aria-label="Permalink to “案”">​</a></h3><p>卦以损三益上成义，则上者受益之极，卦之主也。故“无咎”、“可贞”、“利有攸往”之辞，皆与卦同。其不言“有孚元吉”者，弗损于下而有益于己，此非有至诚仁爱之心者不能也。盖黎民之生厚，则所以固本寜邦者至矣；仁义之俗成，则其有遗亲后君者鲜矣。其为益孰大于是？然其不损于下者，乃所以自损于己也。此所以合乎卦义，有孚元善之德也。得臣无家，则又极言弗损之规模与夫获益之气象。自其弗损之心而言之，为天下君而不自利于己；自其得益之量而言之，莫匪王臣而不视为私属，皆所谓“得臣无家”，王道之至也。盖五上二爻相蒙为义，五之虚中既已格乎鬼神而元吉，则彖所谓“有孚元吉”者巳备，故于此爻遂究其说以终其义也。九二之“弗损”谓损己益之谓益人，此爻之“弗损”谓损人益之谓益己，辞同而指异者，卦义损下益上，故在下卦为自损，在上卦为受益。卦名以损下益上为义，卦辞则泛论损所当损而损中有益也。六爻之辞，其以上下体分损益，则根乎卦名；其言损所当损而损中有益，则又根乎卦辞。</p><p>象曰：弗损益之大得志也</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>居上不损下而反益之，是君子大得行其志也。君子之志，唯在益于人而已。</p>',144)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
